function accRangeBar(w) {
  return `
    <div class="filters">
      <select id="accRange" aria-label="Elegir el periodo">
        ${SALES_RANGES.map((r) => `<option value="${r.id}"${ui.conta.range === r.id ? " selected" : ""}>${r.label}</option>`).join("")}
