function accTabBar() {
  return `<div class="acc-tabs" role="tablist">
    ${ACC_TABS.map(([id, label]) =>
      `<button class="acc-tab${ui.conta.tab === id ? " is-on" : ""}" data-action="acc-tab" data-id="${id}" role="tab" aria-selected="${ui.conta.tab === id}">${label}</button>`
